// Read one installation email into the shape the dispatch app expects.
//
// mHelp board assignments carry a labelled table -- Account Name, Email,
// Address, Job ID -- so they are read exactly, by matching labels, with no AI
// involved. That is deliberate: it is free, it is the same every time, and it
// cannot invent a value. Anything it cannot read confidently is passed on with
// needs_review set, which puts it in the review queue rather than into a job.
//
// Emails carrying an Excel install sheet are NOT parsed here. The dispatch app
// already knows how to read those workbooks; this hands the email over and
// lets that screen do it.

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  // Outlook gives HTML for most mail. Flatten it to text, keeping line breaks,
  // because every label below sits at the start of its own line.
  const html = m.body?.content ?? m.bodyHtml ?? '';
  const plain = m.bodyPreview ?? '';
  const text = (html
    ? html
        // Style and script blocks first. Their contents are not markup, so
        // stripping tags alone would tip three kilobytes of CSS into the stored
        // email body. mHelp happens to wrap its CSS in an HTML comment, which
        // hides it by accident -- this does not rely on that continuing.
        .replace(/<style[\s\S]*?<\/style>/gi, ' ')
        .replace(/<script[\s\S]*?<\/script>/gi, ' ')
        .replace(/<!--[\s\S]*?-->/g, ' ')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/(p|div|tr|h\d)>/gi, '\n')
        .replace(/<[^>]+>/g, ' ')
        // Named entities, then numeric ones. Outlook sometimes sends a real
        // apostrophe and sometimes &#8217;, and a customer stored as
        // "Luigi&#8217;s Pizza" is a name a contractor reads on a work order.
        .replace(/&nbsp;/gi, ' ')
        .replace(/&amp;/gi, '&')
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&apos;/gi, "'")
        .replace(/&quot;/gi, '"')
        .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
        .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(parseInt(dec, 10)))
    : plain)
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const lines = text.split('\n').map((l) => l.trim());

  // Value on the same line as its label. Stops at the next label so a blank
  // field cannot swallow the one after it.
  const field = (label) => {
    const re = new RegExp('^' + label + '\\s*:\\s*(.*)$', 'i');
    for (const line of lines) {
      const hit = line.match(re);
      if (hit) return (hit[1] || '').trim() || null;
    }
    return null;
  };

  // The line that follows a label, for values that wrap (the address does).
  const lineAfter = (label) => {
    const re = new RegExp('^' + label + '\\s*:', 'i');
    for (let i = 0; i < lines.length; i += 1) {
      if (re.test(lines[i])) {
        for (let j = i + 1; j < lines.length && j <= i + 3; j += 1) {
          const next = lines[j];
          if (next && !/^[A-Za-z /]{3,30}:/.test(next)) return next;
        }
        return null;
      }
    }
    return null;
  };

  const accountName = field('Account Name') || field('Customer Name');
  const jobId = field('Job ID');
  const description = field('Description');
  const emailField = field('Email');

  // "Three Bridges Cafe - 510245871" -- the trailing number is the account.
  let accountNumber = null;
  if (accountName) {
    const tail = accountName.match(/[-\u2013]\s*(\d{4,})\s*$/);
    if (tail) accountNumber = tail[1];
  }

  // Address line, then "City, ST 08887" underneath it.
  const addressLine = field('Address');
  const cityLine = lineAfter('Address');
  let city = null;
  let state = null;
  let zip = null;
  if (cityLine) {
    const parts = cityLine.match(/^(.+?),\s*([A-Za-z]{2})\s+(\d{5}(?:-\d{4})?)\s*$/);
    if (parts) {
      city = parts[1].trim();
      state = parts[2].toUpperCase();
      zip = parts[3];
    }
  }

  const hasAttachment = Boolean(m.hasAttachments);
  const looksLikeMhelp = Boolean(accountName && jobId);

  const missing = [];
  if (!accountName) missing.push('customer_name');
  if (!addressLine) missing.push('installation_address');
  if (!city) missing.push('city');
  if (!state) missing.push('state');

  // An attachment means an install sheet the dispatch app parses itself, so it
  // goes to the review queue whatever else was readable.
  let needsReview = false;
  let reviewReason = null;
  if (hasAttachment && !looksLikeMhelp) {
    needsReview = true;
    reviewReason = 'The email has an attachment to read on the review screen.';
  } else if (!looksLikeMhelp) {
    needsReview = true;
    reviewReason = 'This is not an mHelp assignment; read it by hand.';
  } else if (missing.length > 0) {
    needsReview = true;
    reviewReason = 'Could not read: ' + missing.join(', ') + '.';
  }

  out.push({
    json: {
      source_email_message_id: m.id,
      source_email_conversation_id: m.conversationId ?? null,
      source_email_subject: m.subject ?? null,
      source_email_sender:
        m.from?.emailAddress?.address ?? m.sender?.emailAddress?.address ?? null,
      source_email_received_at: m.receivedDateTime ?? null,

      raw_text: text || '(the email had no readable body)',

      customer_name: accountName,
      site_name: accountName,
      installation_address: addressLine,
      city,
      state,
      zip,

      site_contact_email: emailField,

      work_order_number: jobId,
      account_number: accountNumber,

      installation_notes: description,

      missing_fields: missing,
      needs_review: needsReview,
      review_reason: reviewReason,
    },
  });
}

return out;
